package com.opensocket.aievent.core.iam.authentication.domain;import static org.junit.jupiter.api.Assertions.*;import java.time.Instant;import org.junit.jupiter.api.Test;class SubjectSecurityStateTest{@Test void locksAtThreshold(){var p=PasswordPolicy.secureDefault();var at=Instant.parse("2026-07-23T00:00:00Z");var s=SubjectSecurityState.initial(CredentialSubjectType.HUMAN_USER,"u1");for(int i=0;i<p.failedAttemptThreshold();i++)s=s.recordFailure(at,p);assertTrue(s.lockedAt(at));}}
